def b(title, text):
    return {"title": title, "text": text}


def page(kicker, title, deck, left, right, callout, features, sections=(), **extra):
    return {"kicker": kicker, "title": title, "deck": deck, "left": left, "right": right,
            "callout": callout, "feature_ids": features, "section_ids": list(sections), **extra}


